// UGO push/notification worker — the *offline shell* cache is handled by the Workbox worker
// (dist/sw.js, generated by VitePWA), so this file only owns push + notification UI.
// It is intentionally a classic script (public/ is copied verbatim, no bundler), which means:
//   - no `import.meta`; URLs are relative to the registration scope (== Vite base)
//   - `clients` is NOT a global in a ServiceWorkerGlobalScope, hence `self.clients`

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  let data = { title: 'UGO · Nova Oferta de Serviço', body: 'Você recebeu uma nova solicitação de trabalho.', url: './' };
  if (event.data) {
    try {
      data = event.data.json();
    } catch (e) {
      data.body = event.data.text() || data.body;
    }
  }

  const options = {
    body: data.body,
    icon: './pwa-192x192.png',
    badge: './icon.svg',
    vibrate: [200, 100, 200],
    data: { url: data.url || './' },
    actions: [
      { action: 'open', title: 'Ver Oferta' }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = new URL(event.notification.data?.url || './', self.location).href;

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (const client of windowClients) {
        if (client.url.startsWith(self.location.origin) && 'focus' in client) {
          client.focus();
          client.navigate(targetUrl);
          return;
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});
